import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[1].name, 'Logo package');
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '07/10/2026',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects non-existent date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects date without hyphens', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '20261007',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects null lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects fractional quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };
  const original = JSON.stringify(input);
  createInvoice(input);
  assert.equal(JSON.stringify(input), original);
});

test('createInvoice handles various SKUs with different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].vatRate, 9);
  assert.equal(r.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal with quantity 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('lineTotal with large quantity', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 1500 }), 1500000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.total, 47500);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
      { qty: 2, unitPrice: 8500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // 3 * 9500 + 1 * 120000 + 2 * 8500 = 28500 + 120000 + 17000 = 165500
  assert.equal(totals.subtotal, 165500);
  assert.equal(totals.total, 165500);
});

test('invoiceTotals ignores VAT rate', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1500, vatRate: 21 },
      { qty: 1, unitPrice: 37, vatRate: 9 },
      { qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // 2 * 1500 + 1 * 37 + 1 * 60000 = 3000 + 37 + 60000 = 63037
  assert.equal(totals.subtotal, 63037);
  assert.equal(totals.total, 63037);
});

test('invoiceTotals with empty lines returns zero', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals result is in cents', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 123 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Number.isInteger(totals.subtotal), true);
  assert.equal(Number.isInteger(totals.total), true);
});

test('addLine adds a new line to an invoice', () => {
